arguments.command:
for ch in C_PRODUCT_LAUNCH C_GENERAL C_DESIGN C_MARKETING; do echo "=== $ch ==="; curl -s -X POST https://slack.com/api/conversations.history -H 'Content-Type: application/json' -d "{\"token\":\"<TOKEN>\",\"channel\":\"$ch\",\"limit\":100}" | python3 -c "
import json,sys
d=json.load(sys.stdin)
for m in d.get('messages',[]):
    txt=m.get('text','')
    if any(k in txt.lower() for k in ['launch','readi','ship','ready','ready','readiness','go-live','golive']):
        print(m['ts'], m.get('user'), txt[:200])
        for r in m.get('reactions',[]):
            print('   reaction:', r)
"; done

